const $=id=>document.getElementById(id);let current=null,filename='',demo=false,sequence=0,extra=null,additions=[],templateBytes=null,templatePromise=null;
function notice(s,error=false){$('notice').hidden=!s;$('notice').textContent=s;$('notice').classList.toggle('error',error)}
function changed(){if(!current)return;let valid=true;try{if($('name').value!==current.name)encodeName($('name').value);if($('money').value.trim()==='')throw Error();const n=Number($('money').value);if(!Number.isInteger(n)||n<0||n>PROFILE.maxMoney)throw Error();}catch{valid=false}let updates={party:[],items:[]};try{updates=extraChanges()}catch{valid=false}const dirty=$('name').value!==current.name||Number($('money').value)!==current.money||updates.party.length>0||updates.items.length>0||(updates.bag?.length||0)>0||additions.length>0||rosterDrafts.size>0;$('export').disabled=demo||!valid||!dirty||detailDirty||!!bagEditor?.pending();$('changeinfo').textContent=bagEditor?.pending()?'กดบันทึกไอเทมลงรายการ หรือยกเลิกค่าที่ยังไม่บันทึกก่อนดาวน์โหลด':detailDirty?'กดบันทึกค่าตัวนี้ลงรายการ หรือยกเลิกค่าที่ยังไม่บันทึกก่อนดาวน์โหลด':demo?'ข้อมูลตัวอย่างเท่านั้น ไม่สามารถดาวน์โหลดเป็นเซฟเกมได้':!valid?'ตรวจชื่อ เงิน HP และจำนวนไอเทมให้ตรงตามเงื่อนไข':dirty?'พร้อมส่งออกเป็นไฟล์ใหม่ โดยคงนามสกุลเดิม':'ยังไม่มีการเปลี่ยนแปลง';}
let bagEditor=null;
let rosterDrafts=new Map(),viewBox=0,selectedKey=null,roster=null,detailDirty=false;
function show(){additions=[];rosterDrafts.clear();selectedKey=null;detailDirty=false;const s=current;$('empty').hidden=true;$('form').hidden=false;$('name').value=s.name;$('money').value=s.money;$('tid').textContent=String(s.tid).padStart(5,'0');$('slot').textContent=demo?'ตัวอย่าง':`${s.active.slot+1} / ครั้งที่ ${s.active.counter}`;$('check').textContent=demo?'ข้อมูลจำลอง':'14 / 14 ผ่าน';$('state').textContent=demo?'โหมดตัวอย่าง':'เปิดเซฟแล้ว';$('backup').hidden=demo;$('fileinfo').hidden=demo;$('fileinfo').textContent=demo?'':filename+' · 128 KB';renderCreator();renderExtras();notice(demo?'นี่คือข้อมูลตัวอย่างสำหรับลองหน้าจอ เมื่อมีเซฟจริงแล้วให้เลือกไฟล์ด้านซ้าย':s.name.includes('�')?'ชื่อเดิมมีตัวอักษรที่ยังแสดงไม่ได้ หากไม่แก้ช่องชื่อ โปรแกรมจะเก็บชื่อเดิมครบทุกไบต์':'ฟังก์ชันเพิ่มโปเกมอนผ่านการทดสอบในเกมจากคุณแล้ว เก็บสำเนาเซฟต้นฉบับก่อนแก้ไข');changed();}
$('savefile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const token=++sequence;current=null;demo=false;$('form').hidden=true;$('empty').hidden=false;$('fileinfo').hidden=true;$('state').textContent='กำลังตรวจสอบ';try{if(!/\.(sav|srm)$/i.test(file.name))throw Error('เลือกไฟล์ .sav หรือ .srm ที่ส่งออกจากการ Save ในเกม');if(file.size!==131072)throw Error('รุ่นนี้รองรับเซฟขนาด 128 KB เท่านั้น');const bytes=new Uint8Array(await file.arrayBuffer());if(token!==sequence)return;current=parseSave(bytes);filename=file.name;show();}catch(err){if(token!==sequence)return;notice(err.message,true);$('state').textContent='เปิดไฟล์ไม่ได้';}finally{e.target.value=''}});
$('demo').onclick=()=>{++sequence;demo=true;current={name:'OOTEE',money:3000,tid:12345};show()};
$('name').oninput=changed;$('money').oninput=changed;$('max').onclick=()=>{$('money').value=PROFILE.maxMoney;changed()};$('reset').onclick=()=>{++sequence;show()};
function download(bytes,name){const url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('backup').onclick=()=>{if(current&&!demo)download(current.bytes,filename.replace(/\.(sav|srm)$/i,'_backup.$1'))};
$('form').onsubmit=e=>{e.preventDefault();if(!current||demo||$('export').disabled)return;try{let output=editExtended(current.bytes,{name:$('name').value,money:Number($('money').value),...extraChanges()});output=editBag(output,bagEditor?.changes()||[]);output=addPokemon(output,additions,templateBytes);output=editRoster(output,[...rosterDrafts.values()]);download(output,filename.replace(/\.(sav|srm)$/i,'_edited.$1'));notice('ส่งไฟล์ให้เบราว์เซอร์ดาวน์โหลดแล้ว เก็บเซฟต้นฉบับไว้ก่อนนำไฟล์ที่แก้เข้าเกม');}catch(err){notice(err.message,true)}};

function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function renderExtras(){const root=$('extras');root.replaceChildren();bagEditor=null;if(demo){root.append(element('p','เปิดเซฟจริงเพื่อดูหมวดกระเป๋าและเพิ่ม/แก้ไขไอเทม','help'));return}try{bagEditor=mountBag(root,current.bytes,changed)}catch(err){root.append(element('p','กระเป๋ายังไม่รองรับข้อมูลนี้: '+err.message,'help'))}}
function extraChanges(){return {party:[],items:[],bag:bagEditor?.changes()||[]}}

async function loadTemplates(){if(templateBytes)return templateBytes;if(!templatePromise)templatePromise=(async()=>{const response=await fetch('./mon-templates.bin');if(!response.ok)throw Error('โหลดข้อมูลโปเกมอนไม่สำเร็จ ลองอีกครั้ง');const data=new Uint8Array(await response.arrayBuffer());const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data)),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==TEMPLATE_SHA256)throw Error('ข้อมูลโปเกมอนไม่ครบหรือเป็นรุ่นเก่า โปรดรีเฟรชเว็บ');templateBytes=data;return data})().catch(e=>{templatePromise=null;throw e});return templatePromise;}
function renderCreator(){const root=$('creator');root.replaceChildren();root.append(element('h2','เพิ่มโปเกมอน'),element('p','เลือกชนิด เลเวล และปลายทาง จากนั้นกดเพิ่มในรายการ ก่อนดาวน์โหลดเซฟ','help'));if(demo){$('roster').replaceChildren();root.append(element('p','เปิดเซฟจริงเพื่อเพิ่มโปเกมอนเข้า Party หรือ PC','help'));return;}try{capacity(current.bytes)}catch(e){root.append(element('p',e.message,'help'));return;}
const searchLabel=element('label','ค้นหาชื่อหรือฟอร์มโปเกมอน');searchLabel.htmlFor='species-search';const search=element('input');search.id=searchLabel.htmlFor;search.placeholder='เช่น Charizard, Mega, Hisui, อโลลา';search.type='search';const label=element('label','ชนิดโปเกมอน');label.htmlFor='new-species';const species=element('select');species.id=label.htmlFor;
species.hidden=true;species.setAttribute('aria-hidden','true');label.removeAttribute('for');label.textContent='เลือกโปเกมอนจากรูป';
const selectedPreview=element('div',undefined,'species-preview');selectedPreview.setAttribute('aria-live','polite');const grid=element('div',undefined,'species-grid');grid.setAttribute('role','group');grid.setAttribute('aria-label','รายชื่อโปเกมอนพร้อมรูป');const more=element('button','แสดงเพิ่ม','secondary');more.type='button';let visible=24,results=[];
const renderSelection=()=>{const selected=MON_INDEX.find(m=>String(m.id)===species.value);selectedPreview.replaceChildren();if(selected){selectedPreview.append(monImage(selected.id,selected.name,'selected-sprite'),element('strong',selected.name));if(selected.unavailable)selectedPreview.append(element('p',selected.unavailable,'help'));}else selectedPreview.append(element('p','ไม่พบโปเกมอน ลองค้นหาชื่ออื่น','help'));for(const button of grid.querySelectorAll('button'))button.setAttribute('aria-pressed',String(button.dataset.species===species.value));};
const renderGrid=()=>{grid.replaceChildren();for(const mon of results.slice(0,visible)){const button=element('button',undefined,'species-card');button.type='button';button.dataset.species=String(mon.id);button.setAttribute('aria-label','เลือก '+mon.name);const img=monImage(mon.id,'','picker-sprite');img.loading='lazy';button.append(img,element('span',mon.name));if(mon.unavailable){button.classList.add('unavailable');button.append(element('small','ยังเพิ่มไม่ได้'));button.title=mon.unavailable;}button.onclick=()=>{species.value=String(mon.id);renderSelection()};grid.append(button);}more.hidden=visible>=results.length;more.textContent=`แสดงเพิ่ม (${Math.min(visible,results.length)}/${results.length})`;renderSelection();};
const fillOptions=()=>{const old=species.value,q=search.value.trim().toLowerCase();species.replaceChildren();results=MON_INDEX.filter(m=>{const aliases=m.name.toLowerCase().replace('alola','alola อโลลา').replace('hisui','hisui ฮิซุย').replace('mega','mega เมก้า เมกะ').replace('galar','galar กาลาร์').replace('gigantamax','gigantamax gmax ไจแกนทาแมกซ์');return q.split(/\s+/).every(word=>aliases.includes(word))});for(const mon of results){const option=element('option',mon.name);option.value=mon.id;species.append(option);}if([...species.options].some(o=>o.value===old))species.value=old;visible=24;renderGrid();};search.oninput=fillOptions;more.onclick=()=>{visible+=24;renderGrid()};fillOptions();
const levLabel=element('label','เลเวล');levLabel.htmlFor='new-level';const level=element('select');level.id=levLabel.htmlFor;for(let n=1;n<=100;n++){const option=element('option',String(n));option.value=n;level.append(option)}level.value=5;
const destLabel=element('label','ใส่ไว้ที่');destLabel.htmlFor='new-destination';const dest=element('select');dest.id=destLabel.htmlFor;const slotLabel=element('label','ช่องปลายทาง');slotLabel.htmlFor='new-slot';const slotSelect=element('select');slotSelect.id='new-slot';dest.onchange=()=>renderTargetSlots();
const add=element('button','เพิ่มในรายการ','primary');add.type='button';add.id='queue-mon';const message=element('p','โปเกมอนที่เพิ่มจะใช้ชื่อผู้เล่นและ Trainer ID ของเซฟนี้ ท่าและค่าสถานะเริ่มต้นกำหนดตามชนิด/เลเวล ยังไม่ลงทะเบียน Pokédex','help');const feedback=element('p',undefined,'help');feedback.id='creator-feedback';feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');const queue=element('div');queue.id='addition-queue';root.append(searchLabel,search,label,species,selectedPreview,grid,more,levLabel,level,destLabel,dest,slotLabel,slotSelect,message,add,feedback,queue);
add.onclick=async()=>{const token=sequence,source=current;const request={slot:$('new-slot').value===''?undefined:Number($('new-slot').value),species:Number(species.value),level:Number(level.value),destination:dest.value==='party'?'party':'pc',box:dest.value==='party'?undefined:Number(dest.value)};const selectedMeta=MON_INDEX.find(m=>m.id===Number(species.value));if(selectedMeta?.unavailable){feedback.textContent=selectedMeta.unavailable;return;}if(!species.value||!dest.value){feedback.textContent='เลือกโปเกมอนและช่องว่างปลายทางก่อน';return;}if(detailDirty){notice('บันทึกค่าตัวที่กำลังแก้ก่อนเพิ่มโปเกมอน',true);return;}add.disabled=true;feedback.textContent='กำลังเตรียมข้อมูลโปเกมอน…';try{const data=await loadTemplates();if(token!==sequence||source!==current)return;if(request.destination==='pc'&&request.slot===undefined){const before=inspectRoster(addPokemon(current.bytes,additions,data));request.slot=before.boxes[request.box].findIndex(m=>!m);}addPokemon(current.bytes,[...additions,request],data);additions.push(request);feedback.textContent='เพิ่มในรายการแล้ว กดดาวน์โหลดเซฟที่แก้ไขด้านล่างเพื่อบันทึก';renderQueue();changed();}catch(e){feedback.textContent=e.message;}finally{add.disabled=false}};renderQueue();}
function renderQueue(){if(!$('addition-queue'))return;const staged=addPokemon(current.bytes,additions,templateBytes),space=capacity(staged),dest=$('new-destination'),old=dest.value;dest.replaceChildren();const p=element('option',`Party — ${space.party}/6 ตัว`);p.value='party';p.disabled=space.party>=6;dest.append(p);for(const b of space.boxes){const o=element('option',`PC กล่อง ${b.box+1} — ว่าง ${b.free}/30 ช่อง`);o.value=b.box;o.disabled=b.free===0;dest.append(o);}if([...dest.options].some(o=>o.value===old&&!o.disabled))dest.value=old;else{const first=[...dest.options].find(o=>!o.disabled);dest.value=first?.value||'';}
const list=$('addition-queue');list.replaceChildren();if(additions.length)list.append(element('h3',`รอบันทึก ${additions.length} ตัว`));additions.forEach((request,i)=>{const row=element('div',undefined,'queued-row');row.append(monImage(request.species,'','queue-sprite'));row.append(element('span',`${MON_INDEX.find(m=>m.id===request.species).name} Lv.${request.level} → ${request.destination==='party'?'Party':'PC กล่อง '+(request.box+1)}`));const remove=element('button','เอาออก','text-button');remove.type='button';remove.setAttribute('aria-label','เอารายการที่ '+(i+1)+' ออก');remove.onclick=()=>{if(detailDirty){notice('บันทึกหรือยกเลิกค่าตัวที่กำลังแก้ก่อน',true);return;}const before=inspectRoster(addPokemon(current.bytes,additions.slice(0,i),templateBytes));const key=request.destination==='party'?'party:'+before.count:`pc:${request.box}:${request.slot??before.boxes[request.box].findIndex(m=>!m)}`;rosterDrafts.delete(key);if(request.destination==='party'){const removed=before.count;const updated=new Map();for(const [k,c] of rosterDrafts){if(c.destination==='party'&&c.slot>removed){const next={...c,slot:c.slot-1,key:'party:'+(c.slot-1)};updated.set(next.key,next)}else updated.set(k,c)}rosterDrafts=updated;}additions.splice(i,1);selectedKey=null;renderQueue();changed()};row.append(remove);list.append(row)});renderRoster();renderTargetSlots();}

function monImage(id,name,cls){const img=element('img',undefined,cls);img.src=`./sprites/${id}.png`;img.onerror=()=>{img.onerror=null;const matched=MON_INDEX.find(m=>m.name===monName(id));if(matched&&matched.id!==id)img.src=`./sprites/${matched.id}.png`;else{img.removeAttribute('src');img.alt=name||'รูปไม่พร้อม';}};img.alt=name;img.width=64;img.height=64;img.decoding='async';return img}

function stagedRoster(){return inspectRoster(editRoster(addPokemon(current.bytes,additions,templateBytes),[...rosterDrafts.values()]));}
function renderTargetSlots(){if(!roster||!$('new-slot'))return;const select=$('new-slot'),old=select.value,dest=$('new-destination').value;select.replaceChildren();if(dest==='party'){const o=element('option',roster.count<6?`ช่อง ${roster.count+1} — ช่องว่างถัดไป`:'Party เต็ม');o.value='';select.append(o);select.disabled=true;}else{select.disabled=false;const auto=element('option','ช่องว่างแรก');auto.value='';select.append(auto);(roster.boxes[Number(dest)]||[]).forEach((mon,slot)=>{if(mon)return;const o=element('option',`ช่อง ${slot+1} — ว่าง`);o.value=slot;select.append(o)});if([...select.options].some(o=>o.value===old))select.value=old;}}
function renderRoster(){const root=$('roster');root.replaceChildren();if(demo)return;try{roster=stagedRoster()}catch(e){root.append(element('p',e.message,'help'));return;}root.append(element('h2','Party / PC'),element('p','แตะโปเกมอนเพื่อแก้ค่า หรือแตะช่องว่างเพื่อเพิ่มตัวใหม่','help'));const party=element('div',undefined,'roster-grid party-grid');party.setAttribute('aria-label','ช่อง Party');roster.party.forEach((m,i)=>party.append(slotCard(m,{destination:'party',slot:i})));root.append(element('h3',`Party · ${roster.count}/6`),party);
const label=element('label','กล่อง PC');label.htmlFor='view-box';const select=element('select');select.id=label.htmlFor;roster.boxes.forEach((box,i)=>{const o=element('option',`กล่อง ${i+1} · ${box.filter(Boolean).length}/30 ตัว`);o.value=i;select.append(o)});select.value=viewBox;select.onchange=()=>{if(detailDirty){select.value=viewBox;notice('บันทึกหรือยกเลิกค่าที่กำลังแก้ก่อนเปลี่ยนกล่อง',true);return;}viewBox=Number(select.value);renderRoster()};root.append(label,select);const grid=element('div',undefined,'roster-grid pc-grid');grid.setAttribute('aria-label','PC กล่อง '+(viewBox+1));roster.boxes[viewBox].forEach((m,i)=>grid.append(slotCard(m,{destination:'pc',box:viewBox,slot:i})));root.append(grid);const detail=element('section');detail.id='mon-detail';root.append(detail);if(selectedKey){const mon=[...roster.party,...roster.boxes.flat()].find(m=>m?.key===selectedKey);if(mon)renderMonDetail(mon)}
}
function slotCard(mon,location){const button=element('button',undefined,'slot-card'+(!mon?' vacant':''));button.type='button';const position=location.destination==='party'?`Party ช่อง ${location.slot+1}`:`PC กล่อง ${location.box+1} ช่อง ${location.slot+1}`;button.setAttribute('aria-label',`${position}: ${mon?mon.speciesName+' เลเวล '+mon.level:'ว่าง เพิ่มโปเกมอน'}`);button.append(element('span',String(location.slot+1),'slot-number'));if(mon){button.append(monImage(mon.mapped??mon.species,'','picker-sprite'),element('span',mon.speciesName),element('small',mon.egg?'ไข่':`Lv.${mon.level}`));if(rosterDrafts.has(mon.key))button.append(element('small','แก้แล้ว','draft-tag'));button.setAttribute('aria-pressed',String(selectedKey===mon.key));}else button.append(element('strong','＋'),element('span','ว่าง'));button.onclick=()=>{if(detailDirty){notice('กดบันทึกค่าตัวนี้ลงรายการ หรือยกเลิกก่อนเลือกช่องอื่น',true);return;}if(mon){selectedKey=mon.key;renderRoster();$('mon-detail').scrollIntoView({block:'nearest',behavior:'smooth'});$('mon-detail-title').focus({preventScroll:true})}else{if(location.destination==='party'&&location.slot!==roster.count){notice(`Party ต้องเพิ่มเรียงช่อง เริ่มที่ช่อง ${roster.count+1}`);return;}$('new-destination').value=location.destination==='party'?'party':String(location.box);renderTargetSlots();$('new-slot').value=location.destination==='pc'?String(location.slot):'';$('creator-feedback').textContent='ปลายทาง: '+position;$('creator').scrollIntoView({block:'start',behavior:'smooth'});$('species-search').focus({preventScroll:true});}};return button;}
function renderMonDetail(mon){
 const root=$('mon-detail');root.replaceChildren();root.className='mon-detail';
 const title=element('h3',`${mon.speciesName} · Lv.${mon.level}`);title.id='mon-detail-title';title.tabIndex=-1;
 const head=element('div',undefined,'detail-head');head.append(monImage(mon.mapped??mon.species,'','selected-sprite'),title);root.append(head,element('p',`${mon.destination==='party'?'Party':`PC กล่อง ${mon.box+1}`} · ช่อง ${mon.slot+1}`,'help'));
 if(mon.egg){root.append(element('p','ไข่โปเกมอน — ยังไม่รองรับการแก้ข้อมูล','help'));return;}
 const feedback=element('p',undefined,'help');feedback.setAttribute('role','status');
 const dirty=()=>{detailDirty=true;feedback.textContent='ยังไม่บันทึกค่าตัวนี้';changed()};
 const field=(label,id,type='text')=>{const lab=element('label',label);lab.htmlFor=id;const input=element(type==='select'?'select':'input');input.id=id;if(type!=='select')input.type=type;root.append(lab,input);return input;};
 const nick=field('ชื่อเล่น','detail-nickname');nick.value=mon.nickname;nick.maxLength=10;nick.oninput=dirty;root.append(element('p','ชื่อใหม่ใช้อังกฤษ/ตัวเลข 1–10 ตัวอักษร ชื่อภาษาไทยเดิมจะเก็บไว้เมื่อไม่แก้','help'));
 const level=field('เลเวล','detail-level','number');level.min=1;level.max=100;level.step=1;level.inputMode='numeric';level.value=mon.level;level.disabled=!mon.editable;root.append(element('p','1–100 · Stats คิดตาม Level Cap ของเซฟ การเปลี่ยนเลเวลไม่เปลี่ยนท่าหรือวิวัฒนาการอัตโนมัติ','help'));
 const gender=field('เพศ','detail-gender','select');for(const g of mon.genderChoices){const o=element('option',({male:'ตัวผู้ ♂',female:'ตัวเมีย ♀',none:'ไม่มีเพศ'})[g]);o.value=g;gender.append(o)}gender.value=mon.gender;gender.disabled=mon.genderChoices.length===1;gender.onchange=dirty;
 const nature=field('นิสัย (Nature)','detail-nature','select');for(let n=0;n<25;n++){const up=Math.floor(n/5)+1,down=n%5+1,label=up===down?'เป็นกลาง':`+${STAT_NAMES[up]} / −${STAT_NAMES[down]}`;const o=element('option',`${NATURES[n]} · ${label}`);o.value=n;nature.append(o)}nature.value=mon.nature;nature.disabled=!mon.editable;
 const ability=field('Ability','detail-ability','select');for(const a of mon.abilities){const o=element('option',`${a.name} · ${a.slot===2?'Hidden Ability':'ช่อง '+(a.slot+1)}`);o.value=a.slot;ability.append(o)}if(!mon.abilities.some(a=>a.slot===mon.abilitySlot)){const o=element('option','คง Ability เดิม');o.value=mon.abilitySlot;ability.append(o)}ability.value=mon.abilitySlot;ability.disabled=roster.ctx.flag(0x3a);ability.onchange=dirty;if(ability.disabled)root.append(element('p','เซฟนี้เปิดสุ่ม Ability จึงคงค่าช่อง Ability เดิม','help'));
 const searchable=(label,id,options,current)=>{
  const lab=element('label',label);lab.htmlFor=id;
  const search=element('input');search.id=id+'-search';search.type='search';search.placeholder='พิมพ์บางส่วนของชื่อ เช่น a';search.autocomplete='off';search.setAttribute('aria-label','ค้นหา '+label);
  const select=element('select');select.id=id;
  const all=Object.entries(options).map(([value,item])=>({value:String(value),name:value==='0'&&id.includes('move')?'— ไม่มีท่า —':item.name}));
  if(!all.some(x=>x.value===String(current)))all.push({value:String(current),name:`คงค่าเดิม #${current}`});
  for(const item of all){const option=element('option',item.name);option.value=item.value;select.append(option)}select.value=String(current);
  const results=element('div',undefined,'search-suggestions');results.id=id+'-results';results.hidden=true;results.setAttribute('role','group');results.setAttribute('aria-label','ผลค้นหา '+label);search.setAttribute('aria-controls',results.id);
  const count=element('p',undefined,'suggestion-count');count.setAttribute('role','status');count.hidden=true;
  const close=()=>{results.hidden=true;count.hidden=true};
  const fill=()=>{const q=search.value.trim().toLocaleLowerCase(),matches=all.filter(item=>item.name.toLocaleLowerCase().includes(q));results.replaceChildren();results.hidden=false;count.hidden=false;count.textContent=matches.length?`พบ ${matches.length} รายการ · แตะเพื่อเลือก`:'ไม่พบชื่อที่ตรง ลองพิมพ์ใหม่';for(const item of matches){const choice=element('button',item.name,'suggestion-option');choice.type='button';choice.onpointerdown=e=>e.preventDefault();choice.dataset.value=item.value;choice.setAttribute('aria-pressed',String(select.value===item.value));choice.onclick=()=>{select.value=item.value;search.value=item.name;close();dirty();select.focus({preventScroll:true})};choice.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();search.focus();close()}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();(e.key==='ArrowDown'?choice.nextElementSibling:choice.previousElementSibling)?.focus()}};results.append(choice)}};
  search.oninput=fill;search.onfocus=fill;search.onkeydown=e=>{if(e.key==='Escape'){close()}if(e.key==='ArrowDown'){e.preventDefault();if(results.hidden)fill();results.querySelector('button')?.focus()}if(e.key==='Enter')e.preventDefault()};
  const wrap=element('div',undefined,'search-field');wrap.append(lab,search,count,results,select);wrap.addEventListener('focusout',e=>{if(!wrap.contains(e.relatedTarget))close()});select.onchange=()=>{search.value='';close();dirty()};root.append(wrap);return select;
 };

 const held=searchable('ไอเทมที่ถือ','detail-held',HELD_ITEMS,mon.heldItem);const moveFields=mon.moves.map((id,i)=>searchable(`ท่าที่ ${i+1}`,`detail-move-${i}`,MOVES,id));root.append(element('p','เลือกท่าได้ 4 ช่อง อย่างน้อย 1 ท่าและไม่ซ้ำกัน ท่าที่เปลี่ยนใน Party เริ่มที่ 1 PP; รักษาที่ Pokémon Center เพื่อเติม PP','help'));
 root.append(element('h3','EV / Stats'),element('p','IV: ROM นี้ไม่มี IV รายตัว จึงแก้ไม่ได้','help'));
 let values=mon.ev.slice();const evFields=[],statFields=[],total=element('p',undefined,'ev-total');
 const readLevel=()=>{const value=Number(level.value);if(level.value.trim()===''||!Number.isInteger(value)||value<1||value>100)throw Error('เลเวลต้องเป็นจำนวนเต็ม 1–100');return value};
 const previewMon=()=>({...mon,nature:Number(nature.value),level:readLevel()});
 const readEV=()=>{if(!mon.editable)return mon.ev.slice();const next=evFields.map(f=>{if(f.value.trim()==='')throw Error('กรอก EV ให้ครบ');return Number(f.value)});if(next.some(n=>!Number.isInteger(n)||n<0||n>252)||next.reduce((a,b)=>a+b,0)>510)throw Error('EV แต่ละค่า 0–252 รวมไม่เกิน 510');return next};
 const refresh=()=>{if(!mon.editable)return;const stats=calculateStats(previewMon(),values,roster.ctx);evFields.forEach((f,i)=>f.value=values[i]);statFields.forEach((f,i)=>{f.value=stats[i];f.setCustomValidity('')});total.textContent=`EV รวม ${values.reduce((a,b)=>a+b,0)} / 510`;};
 if(mon.editable){const table=element('table',undefined,'stat-table'),thead=element('thead'),tr=element('tr');['ค่า','EV','Stats'].forEach(t=>tr.append(element('th',t)));thead.append(tr);table.append(thead);const tbody=element('tbody');table.append(tbody);
 STAT_NAMES.forEach((name,i)=>{const row=element('tr'),label=element('th',name);label.scope='row';row.append(label);for(const kind of ['ev','stats']){const cell=element('td'),input=element('input');input.type='number';input.inputMode='numeric';input.step=1;input.min=kind==='ev'?0:1;input.max=kind==='ev'?252:65535;input.setAttribute('aria-label',`${name} ${kind.toUpperCase()}`);input.id=`detail-${kind}-${i}`;cell.append(input);row.append(cell);if(kind==='ev'){evFields.push(input);input.oninput=()=>{dirty();try{values=readEV();const stats=calculateStats(previewMon(),values,roster.ctx);statFields.forEach((f,j)=>{f.value=stats[j];f.setCustomValidity('')});total.textContent=`EV รวม ${values.reduce((a,b)=>a+b,0)} / 510`}catch(e){feedback.textContent=e.message}}}else{statFields.push(input);input.oninput=()=>{input.setCustomValidity('');dirty()};input.onchange=()=>{try{values=evForStat(previewMon(),readEV(),roster.ctx,i,input.value.trim()===''?NaN:Number(input.value));refresh();feedback.textContent='ปรับ EV ให้ได้ Stats ที่เลือกแล้ว ยังไม่บันทึกค่าตัวนี้'}catch(e){feedback.textContent=e.message;input.setCustomValidity(e.message)}changed()};}}tbody.append(row)});root.append(table,total,element('p','EV 0–252 ต่อค่า รวมไม่เกิน 510 · คิดตามนิสัยและ Level Cap ของเซฟ · ค่า PC คำนวณตอนถอนเข้า Party','help'));if(roster.ctx.flag(0x40))root.append(element('p','เซฟเปิดโหมดไม่นำ EV ไปคิด Stats ค่าจะถูกเก็บไว้แต่ไม่มีผลในโหมดนี้','help'));}
 else root.append(element('p',mon.reason+' — ยังแก้ชื่อ เพศ ไอเทม และท่าได้','help'));
 level.oninput=()=>{dirty();try{readLevel();values=readEV();refresh()}catch(e){feedback.textContent=e.message}};
 nature.onchange=()=>{dirty();try{values=readEV();refresh()}catch(e){feedback.textContent=e.message}};
 let hp=null;if(mon.destination==='party'){hp=field('HP ปัจจุบัน (เว้นค่าเดิมเพื่อปรับตาม HP สูงสุดอัตโนมัติ)','detail-hp','number');hp.min=0;hp.max=65535;hp.step=1;hp.value=mon.hp;hp.oninput=dirty;}
 root.append(feedback);const actions=element('div',undefined,'actions'),apply=element('button','บันทึกค่าตัวนี้ลงรายการ','primary'),cancel=element('button','ยกเลิกค่าที่ยังไม่บันทึก','secondary');apply.type=cancel.type='button';
 apply.onclick=()=>{try{const targetLevel=readLevel();values=readEV();if(mon.editable){const stats=calculateStats(previewMon(),values,roster.ctx);if(statFields.some((f,i)=>f.value.trim()===''||Number(f.value)!==stats[i]||!f.checkValidity()))throw Error('Stats ที่กรอกยังไม่ตรงกับ EV โปรดแก้ค่าที่แจ้งก่อน');}const update={...(rosterDrafts.get(mon.key)||{}),key:mon.key,destination:mon.destination,box:mon.box,slot:mon.slot};if(mon.editable)update.ev=values;if(targetLevel!==mon.level)update.level=targetLevel;
 if(nick.value!==mon.nickname)update.nickname=nick.value;if(gender.value!==mon.gender)update.gender=gender.value;if(Number(nature.value)!==mon.nature)update.nature=Number(nature.value);if(Number(ability.value)!==mon.abilitySlot)update.abilitySlot=Number(ability.value);if(Number(held.value)!==mon.heldItem)update.heldItem=Number(held.value);const moves=moveFields.map(f=>Number(f.value));if(moves.some((n,i)=>n!==mon.moves[i]))update.moves=moves;if(hp&&(hp.value.trim()===''||Number(hp.value)!==mon.hp)){if(hp.value.trim()==='')throw Error('กรอก HP ปัจจุบัน');update.hp=Number(hp.value);}const candidates=new Map(rosterDrafts);candidates.set(mon.key,update);editRoster(addPokemon(current.bytes,additions,templateBytes),[...candidates.values()]);rosterDrafts=candidates;detailDirty=false;renderRoster();notice('บันทึกข้อมูลตัวนี้ลงรายการแล้ว กดดาวน์โหลดเซฟที่แก้ไขเพื่อนำเข้าเกม');changed();}catch(e){feedback.textContent=e.message}};
 cancel.onclick=()=>{detailDirty=false;renderRoster();changed()};actions.append(apply,cancel);root.append(actions);refresh();
}

function monName(id){return roster?.party.concat(roster.boxes.flat()).find(m=>m?.species===id)?.speciesName||''}
